def solve(workspace):
    n = workspace.length
    for i in range(n - 1):
        min_idx = i
        for j in range(i + 1, n):
            if workspace.peek(j) < workspace.peek(min_idx):
                min_idx = j
        if min_idx != i:
            # Move element from min_idx to i using adjacent swaps
            # We need to swap (min_idx - 1), (min_idx - 2), ..., i
            # Number of swaps = min_idx - i
            for k in range(min_idx - 1, i - 1, -1):
                workspace.swap_adjacent(k)
